package cn.qiuc.invoice;

import android.content.*;
import android.database.Cursor;
import android.database.sqlite.SQLiteDatabase;
import org.json.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.*;
import java.util.zip.*;

/** Portable, hashed ZIP; imported IDs are merged atomically, never overwrite conflicts. */
public final class PortableBackup {
    private static final LinkedHashMap<String,String> TABLES=new LinkedHashMap<>();
    static{TABLES.put("projects","id,name,reimbursed,pinned,deleted");TABLES.put("people","id,project_id,name,active");TABLES.put("expenses","id,project_id,data,state,version,deleted");TABLES.put("materials","id,project_id,digest,name,path,mime,role,fields,text,expense_id,status,version");TABLES.put("reports","id,project_id,path,total,count,created,status,manifest,xlsx_path,digest");TABLES.put("experience","key,value,enabled");TABLES.put("events","id,kind,subject,created");}
    private final Context context;private final Ledger ledger;
    public PortableBackup(Context c,Ledger l){context=c;ledger=l;}
    public File create()throws Exception{
        File folder=new File(context.getFilesDir(),"exports");folder.mkdirs();File target=new File(folder,"backup-"+Ledger.id()+".zip");boolean done=false;
        synchronized(ledger){try(ZipOutputStream zip=new ZipOutputStream(new FileOutputStream(target))){JSONObject root=new JSONObject().put("format","invoice-assistant-portable").put("version",1).put("created",System.currentTimeMillis());JSONObject tables=new JSONObject(),files=new JSONObject();Map<String,File> sources=new LinkedHashMap<>();SQLiteDatabase db=ledger.getReadableDatabase();
            for(Map.Entry<String,String> table:TABLES.entrySet()){JSONArray rows=new JSONArray();try(Cursor c=db.rawQuery("SELECT "+table.getValue()+" FROM "+table.getKey(),null)){while(c.moveToNext()){JSONObject row=new JSONObject();for(int i=0;i<c.getColumnCount();i++){String key=c.getColumnName(i);Object value=c.isNull(i)?JSONObject.NULL:c.getType(i)==Cursor.FIELD_TYPE_INTEGER?c.getLong(i):c.getString(i);if((key.equals("path")||key.equals("xlsx_path"))&&!value.equals(JSONObject.NULL)&&!String.valueOf(value).isEmpty()){File source=new File(String.valueOf(value));if(!source.isFile())throw new IOException("备份中有文件缺失，请检查原件及报销包");String path="files/"+PrintExport.sha(source)+(key.equals("xlsx_path")?".xlsx":table.getKey().equals("reports")?".pdf":source.getName().endsWith(".pdf")?".pdf":".image");sources.put(path,source);value=path;}row.put(key,value);}rows.put(row);}}tables.put(table.getKey(),rows);}
            File template=new File(context.getFilesDir(),"report-template.xlsx");if(template.exists()){sources.put("files/template.xlsx",template);root.put("template","files/template.xlsx");}
            for(JSONObject m:ReportModel.list(tables.getJSONArray("materials")))if(!m.getString("digest").equals(PrintExport.sha(sources.get(m.getString("path")))))throw new IOException("原件内容已变化，备份已停止");
            for(Map.Entry<String,File> e:sources.entrySet()){files.put(e.getKey(),new JSONObject().put("sha256",PrintExport.sha(e.getValue())).put("size",e.getValue().length()));zip.putNextEntry(new ZipEntry(e.getKey()));Files.copy(e.getValue().toPath(),zip);zip.closeEntry();}
            root.put("tables",tables).put("files",files);zip.putNextEntry(new ZipEntry("manifest.json"));zip.write(root.toString().getBytes(StandardCharsets.UTF_8));zip.closeEntry();done=true;
        }finally{if(!done)target.delete();}}return target;
    }
    public JSONObject inspect(File archive)throws Exception{File stage=new File(context.getCacheDir(),"restore-"+Ledger.id());stage.mkdirs();try{JSONObject manifest=unpack(archive,stage);JSONObject out=new JSONObject().put("projects",manifest.getJSONObject("tables").getJSONArray("projects").length()).put("expenses",manifest.getJSONObject("tables").getJSONArray("expenses").length()).put("materials",manifest.getJSONObject("tables").getJSONArray("materials").length()).put("reports",manifest.getJSONObject("tables").getJSONArray("reports").length()).put("files",manifest.getJSONObject("files").length()).put("digest",PrintExport.sha(archive));return out;}finally{erase(stage);}}
    private JSONObject unpack(File archive,File stage)throws Exception{
        Set<String> entries=new HashSet<>();long total=0;try(ZipInputStream zip=new ZipInputStream(new FileInputStream(archive))){ZipEntry e;while((e=zip.getNextEntry())!=null){String name=e.getName();if(e.isDirectory())continue;if(!name.matches("manifest\\.json|files/[A-Za-z0-9._-]+")||name.contains("..")||!entries.add(name)||entries.size()>5000)throw new IOException("备份包含非法路径或重复文件");File target=new File(stage,name);target.getParentFile().mkdirs();try(OutputStream out=new FileOutputStream(target)){byte[] block=new byte[65536];int n;long size=0;while((n=zip.read(block))!=-1){total+=n;size+=n;if(total>1024L*1024*1024||size>(name.equals("manifest.json")?30L:200L)*1024*1024)throw new IOException("备份展开后过大");out.write(block,0,n);}}}}
        File manifestFile=new File(stage,"manifest.json");if(!manifestFile.isFile())throw new IOException("缺少备份清单");JSONObject root=new JSONObject(new String(Files.readAllBytes(manifestFile.toPath()),StandardCharsets.UTF_8));if(!root.optString("format").equals("invoice-assistant-portable")||root.optInt("version")!=1)throw new IOException("不支持的备份版本");JSONObject files=root.getJSONObject("files");Iterator<String> keys=files.keys();while(keys.hasNext()){String path=keys.next();if(!entries.remove(path)||!path.startsWith("files/"))throw new IOException("备份文件缺失");File file=new File(stage,path);JSONObject expected=files.getJSONObject(path);if(file.length()!=expected.getLong("size")||!PrintExport.sha(file).equals(expected.getString("sha256")))throw new IOException("备份校验失败："+path);}entries.remove("manifest.json");if(!entries.isEmpty())throw new IOException("备份包含清单外文件");JSONObject tables=root.getJSONObject("tables");for(String table:TABLES.keySet()){JSONArray rows=tables.optJSONArray(table);if(rows==null&&table.equals("events")){tables.put("events",new JSONArray());rows=tables.getJSONArray(table);}if(rows==null)throw new IOException("备份缺少数据表");if(rows.length()>20000)throw new IOException("备份记录过多");for(JSONObject row:ReportModel.list(rows)){Set<String> allowed=new HashSet<>(Arrays.asList(TABLES.get(table).split(",")));Iterator<String> names=row.keys();while(names.hasNext())if(!allowed.contains(names.next()))throw new IOException("备份字段无效");for(String column:allowed)if(!row.has(column))throw new IOException("备份字段缺失："+column);for(String pathKey:List.of("path","xlsx_path"))if(row.has(pathKey)&&!row.optString(pathKey).isEmpty()&&!files.has(row.getString(pathKey)))throw new IOException("备份引用了缺失文件");}}
        if(root.has("template")){if(!root.getString("template").equals("files/template.xlsx")||!files.has(root.getString("template")))throw new IOException("模板引用无效");new ReportWorkbook(new File(stage,root.getString("template")));}return root;
    }
    public JSONObject restore(File archive,String expectedDigest)throws Exception{
        if(!PrintExport.sha(archive).equals(expectedDigest))throw new IOException("待恢复文件已变化，请重新选择");File stage=new File(context.getCacheDir(),"restore-"+Ledger.id());stage.mkdirs();List<File> created=new ArrayList<>();boolean done=false;
        try{JSONObject root=unpack(archive,stage);File store=new File(context.getFilesDir(),"restored");store.mkdirs();Map<String,String> paths=new HashMap<>();JSONObject files=root.getJSONObject("files");Iterator<String> it=files.keys();while(it.hasNext()){String path=it.next();File destination=new File(store,new File(path).getName());File source=new File(stage,path);if(destination.exists()){if(!PrintExport.sha(destination).equals(PrintExport.sha(source)))throw new IOException("同名文件内容冲突，恢复已停止");}else{Files.copy(source.toPath(),destination.toPath());created.add(destination);}paths.put(path,destination.getAbsolutePath());}
            int inserted=0; synchronized(ledger){SQLiteDatabase db=ledger.getWritableDatabase();db.beginTransaction();try{for(String table:TABLES.keySet()){String primary=table.equals("experience")?"key":"id";for(JSONObject original:ReportModel.list(root.getJSONObject("tables").getJSONArray(table))){if(table.equals("events")){try(Cursor prior=db.rawQuery("SELECT 1 FROM events WHERE kind=? AND subject=? AND created=?",new String[]{original.getString("kind"),original.getString("subject"),String.valueOf(original.getLong("created"))})){if(prior.moveToFirst())continue;}db.execSQL("INSERT INTO events(kind,subject,created) VALUES(?,?,?)",new Object[]{original.getString("kind"),original.getString("subject"),original.getLong("created")});inserted++;continue;}JSONObject row=new JSONObject(original.toString());for(String pathKey:List.of("path","xlsx_path"))if(row.has(pathKey)&&!row.optString(pathKey).isEmpty())row.put(pathKey,paths.get(row.getString(pathKey)));try(Cursor existing=db.rawQuery("SELECT "+TABLES.get(table)+" FROM "+table+" WHERE "+primary+"=?",new String[]{row.getString(primary)})){if(existing.moveToFirst()){for(int i=0;i<existing.getColumnCount();i++){String key=existing.getColumnName(i);if(key.equals("path")||key.equals("xlsx_path")){String incoming=row.optString(key),old=existing.getString(i);if(incoming.isEmpty()&&old.isEmpty())continue;if(!PrintExport.sha(new File(incoming)).equals(PrintExport.sha(new File(old))))throw new IOException("同一记录的文件内容不同，已停止恢复");}else{Object value=row.get(key);String incoming=value==JSONObject.NULL?null:String.valueOf(value);if(!Objects.equals(incoming,existing.isNull(i)?null:existing.getString(i)))throw new IOException("同一记录已有修改，恢复不会覆盖："+table);}}continue;}}
                        ContentValues values=new ContentValues();for(String key:TABLES.get(table).split(",")){Object value=row.get(key);if(value==JSONObject.NULL)values.putNull(key);else if(value instanceof Number)values.put(key,((Number)value).longValue());else values.put(key,String.valueOf(value));}db.insertOrThrow(table,null,values);inserted++;}}
                try(Cursor check=db.rawQuery("PRAGMA foreign_key_check",null)){if(check.moveToFirst())throw new IOException("恢复记录的项目或人员关联无效");}
                try(Cursor check=db.rawQuery("SELECT m.id FROM materials m LEFT JOIN expenses e ON m.expense_id=e.id WHERE m.expense_id IS NOT NULL AND (e.id IS NULL OR e.project_id!=m.project_id)",null)){if(check.moveToFirst())throw new IOException("恢复材料的费用关联无效");}
                for(JSONObject m:ReportModel.list(root.getJSONObject("tables").getJSONArray("materials")))if(!m.getString("digest").equals(files.getJSONObject(m.getString("path")).getString("sha256")))throw new IOException("材料原件校验记录不匹配");
                File template=new File(context.getFilesDir(),"report-template.xlsx");if(root.has("template")&&!template.exists()){Files.copy(new File(stage,root.getString("template")).toPath(),template.toPath());created.add(template);}ledger.event(db,"backup_restored",expectedDigest);db.setTransactionSuccessful();done=true;
            }finally{db.endTransaction();}}return new JSONObject().put("inserted",inserted);
        }finally{erase(stage);if(!done)for(File f:created)f.delete();}
    }
    static void erase(File file){File[] children=file.listFiles();if(children!=null)for(File c:children)erase(c);file.delete();}
}
